use system.io
use system.os
use system.fs
use system.process
use system.collections.array
use system.collections.list

const MAX_CELLS = 262144

fn parse_int(token String) int
    match token.to_int()
        Some(v): v
        None: panic(f"not an integer: {token}")

fn main()
    let args = Args()
    if args.length() < 1
        eprintln("usage: main <grid-file>")
        exit(1)

    let fs = Fs()
    var text = ""
    match fs.read_file(args.element_at(0))
        Result.Ok(contents): text = contents
        Result.Err(e):
            eprintln("cannot read grid file")
            exit(1)

    // Split on any whitespace; empty tokens are skipped.
    let spaced = text.replace("\r", " ").replace("\n", " ").replace("\t", " ")
    var tokens = List<int>()
    for part in spaced.split(" ")
        if part.length() > 0
            tokens.push(parse_int(part))

    let width = tokens.element_at(0)
    let height = tokens.element_at(1)
    let steps = tokens.element_at(2)
    let n = width * height

    // Host-side staging of the initial grid.
    var init = Array<int, MAX_CELLS>()
    for i in 0..n
        init.set(i, tokens.element_at(3 + i))

    // Ping-pong buffers on the GPU: each step reads one and writes the other,
    // so every cell sees only the values the previous step left.
    gpu var front = Array<int, MAX_CELLS>()
    gpu var back = Array<int, MAX_CELLS>()
    front = init

    var s = 0
    while s < steps
        if s % 2 == 0
            forall i in 0..n
                let x = i % width
                let y = i / width
                let l = (i - 1 if x > 0 else i)
                let r = (i + 1 if x < width - 1 else i)
                let u = (i - width if y > 0 else i)
                let d = (i + width if y < height - 1 else i)
                back[i] = (4 * front[i] + front[l] + front[r] + front[u] + front[d]) / 8
        else
            forall i in 0..n
                let x = i % width
                let y = i / width
                let l = (i - 1 if x > 0 else i)
                let r = (i + 1 if x < width - 1 else i)
                let u = (i - width if y > 0 else i)
                let d = (i + width if y < height - 1 else i)
                front[i] = (4 * back[i] + back[l] + back[r] + back[u] + back[d]) / 8
        s = s + 1

    var result = Array<int, MAX_CELLS>()
    if steps % 2 == 0
        result = front
    else
        result = back

    var total = 0
    for row in 0..height
        var line = ""
        for col in 0..width
            let v = result.element_at(row * width + col)
            total = total + v
            if col > 0
                line = line + " "
            line = line + f"{v}"
        println(line)
    println(f"SUM {total}")
